#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')


def load_csv(name):
    with (ROOT / name).open(newline='') as f:
        return list(csv.DictReader(f))


def money(value):
    return round(float(value), 2)


def blank(value):
    return value is None or str(value).strip() == ''


def annual_metrics(campaign, active_clinics, payment, crate_cost, days_per_dispatch, dispatches_per_year):
    annual_revenue = payment * active_clinics * dispatches_per_year
    annual_drug_cost = (
        float(campaign['drug_cost_per_1000_doses_usd'])
        * active_clinics
        * float(campaign['doses_per_day'])
        * days_per_dispatch
        * dispatches_per_year
        / 1000.0
    )
    annual_crate_cost = crate_cost * dispatches_per_year
    annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost
    return {
        'annual_revenue_usd': money(annual_revenue),
        'annual_drug_cost_usd': money(annual_drug_cost),
        'annual_crate_cost_usd': money(annual_crate_cost),
        'annual_margin_usd': money(annual_margin),
    }


def main():
    manifest = json.loads((ROOT / 'campaign_manifest.json').read_text())
    crate_rows = load_csv('crate_cost.csv')
    billing_rows = load_csv('billing.csv')
    override_rows = load_csv('location_overrides.csv')
    suspension_rows = load_csv('suspensions.csv')

    held_campaign_ids = {
        row['campaign_id']
        for row in suspension_rows
        if row.get('suspension_status') == 'hold'
    }

    campaigns = []
    for region in manifest.get('regions', []):
        for campaign in region.get('campaigns', []):
            if campaign.get('analysis_flag') == 'review' and campaign.get('campaign_id') not in held_campaign_ids:
                campaigns.append(campaign)

    crate_cost_by_tier = {
        row['crate_tier']: float(row['crate_cost_usd'])
        for row in crate_rows
    }

    valid_overrides_by_campaign = {}
    for row in override_rows:
        if row.get('state') != 'approved':
            continue
        if blank(row.get('revision')) or blank(row.get('active_clinics')):
            continue
        campaign_id = row['campaign_id']
        revision = int(row['revision'])
        active_clinics = int(row['active_clinics'])
        current = valid_overrides_by_campaign.get(campaign_id)
        if current is None or revision > current['revision']:
            valid_overrides_by_campaign[campaign_id] = {
                'revision': revision,
                'active_clinics': active_clinics,
            }

    output_campaigns = []
    for campaign in campaigns:
        campaign_id = campaign['campaign_id']
        labels = {campaign['campaign_name'], *campaign.get('alias_labels', [])}
        matches = [
            row for row in billing_rows
            if row.get('status') == 'active' and row.get('campaign_label') in labels
        ]
        if not matches:
            raise ValueError(f'No active billing row found for {campaign_id}')
        billing = max(matches, key=lambda row: row['cycle_tag'])
        payment = float(billing['payment_per_dispatch_per_clinic_usd'])

        override = valid_overrides_by_campaign.get(campaign_id)
        if override is None:
            active_clinics = int(campaign['default_active_clinics'])
        else:
            active_clinics = override['active_clinics']

        crate_tier = campaign['crate_tier']
        if crate_tier not in crate_cost_by_tier:
            raise ValueError(f'No crate cost found for tier {crate_tier}')
        crate_cost = crate_cost_by_tier[crate_tier]

        six = annual_metrics(campaign, active_clinics, payment, crate_cost, 6, 60)
        twelve = annual_metrics(campaign, active_clinics, payment, crate_cost, 12, 30)
        margin_diff = money(twelve['annual_margin_usd'] - six['annual_margin_usd'])

        output_campaigns.append({
            'campaign_id': campaign_id,
            'campaign_name': campaign['campaign_name'],
            'active_clinics': active_clinics,
            'payment_per_dispatch_per_clinic_usd': money(payment),
            'crate_tier': crate_tier,
            'crate_cost_usd': money(crate_cost),
            'annual_revenue_6_day_usd': six['annual_revenue_usd'],
            'annual_drug_cost_6_day_usd': six['annual_drug_cost_usd'],
            'annual_crate_cost_6_day_usd': six['annual_crate_cost_usd'],
            'annual_margin_6_day_usd': six['annual_margin_usd'],
            'annual_revenue_12_day_usd': twelve['annual_revenue_usd'],
            'annual_drug_cost_12_day_usd': twelve['annual_drug_cost_usd'],
            'annual_crate_cost_12_day_usd': twelve['annual_crate_cost_usd'],
            'annual_margin_12_day_usd': twelve['annual_margin_usd'],
            'annual_margin_difference_12_minus_6_usd': margin_diff,
        })

    output_campaigns.sort(key=lambda row: row['campaign_id'])

    total_6 = money(sum(row['annual_margin_6_day_usd'] for row in output_campaigns))
    total_12 = money(sum(row['annual_margin_12_day_usd'] for row in output_campaigns))
    total_diff = money(sum(row['annual_margin_difference_12_minus_6_usd'] for row in output_campaigns))
    abs_diff = money(abs(total_diff))
    threshold = 11000
    decision = 'move_to_12_day' if abs_diff < threshold else 'keep_6_day'

    result = {
        'assumptions': {
            'six_day_model_days_per_dispatch': 6,
            'six_day_model_dispatches_per_year': 60,
            'twelve_day_model_days_per_dispatch': 12,
            'twelve_day_model_dispatches_per_year': 30,
            'crate_cost_usd_is_per_dispatch': True,
            'decision_threshold_usd': threshold,
        },
        'campaigns': output_campaigns,
        'totals': {
            'total_annual_margin_6_day_usd': total_6,
            'total_annual_margin_12_day_usd': total_12,
            'total_annual_margin_difference_12_minus_6_usd': total_diff,
            'absolute_total_margin_difference_usd': abs_diff,
        },
        'recommendation': {
            'decision': decision,
            'justification': (
                f'Absolute total margin difference is ${abs_diff:,.2f}, '
                f'which is {'below' if abs_diff < threshold else 'at or above'} the ${threshold:,.2f} threshold.'
            ),
        },
    }

    with (ROOT / 'vaxcrate_analysis.json').open('w') as f:
        json.dump(result, f, indent=2)
        f.write('\n')

    summary_lines = [
        f'Total 6-day margin in USD: ${total_6:,.2f}',
        f'Total 12-day margin in USD: ${total_12:,.2f}',
        f'Absolute difference in USD: ${abs_diff:,.2f}',
        f'Decision: {decision}',
    ]
    (ROOT / 'vaxcrate_summary.md').write_text('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()

